// Alturas calibradas para o conteudo real da linha (nome + linha de cargo
// opcional + previa + cluster de badges com SLA/tags, que pode quebrar em 2
// linhas por causa do flex-wrap) — nao so pro avatar de 48px. Pior caso
// (cargo preenchido + badges em 2 linhas, ambos opcionais e independentes)
// soma ~90-100px de conteudo real; o buffer abaixo da area util (slot menos
// margin/padding) fica deliberadamente acima disso. Estimativa revisada em
// auditoria de 5 agentes (2026-09-26) que apontou que o ajuste anterior
// (so +16px pra caber a linha de cargo) nao cobria os dois opcionais
// coincidindo. Valores menores voltam a cortar linha / sobrepor no
// virtualizador (estimateSize fixo, sem measureElement).
const ITEM_HEIGHT_BY_DENSITY: Record<DensityMode, number> = {
  comfortable: 124,
  compact: 116,
  dense: 112,
};

const ROW_CLASSES_BY_DENSITY: Record<DensityMode, string> = {
  comfortable: 'min-h-[108px] my-0.5 px-3 py-2.5',
  compact: 'min-h-[100px] my-0.5 px-3 py-2',
  dense: 'min-h-[96px] my-0.5 px-2.5 py-1.5',
};

const SNOOZE_OPTIONS: { value: string; label: string }[] = [
  { value: '1h', label: 'Em 1 hora' },
  { value: '3h', label: 'Em 3 horas' },
  { value: 'tomorrow', label: 'Amanhã às 9h' },
  { value: 'nextweek', label: 'Próxima semana' },
];

const CHANNEL_BADGE_CONFIG: Record<string, { Icon: LucideIcon; bg: string }> = {
  instagram: { Icon: Instagram, bg: 'bg-[hsl(330,80%,55%)]' },
  messenger: { Icon: Facebook, bg: 'bg-[hsl(220,70%,55%)]' },
  telegram: { Icon: Send, bg: 'bg-[hsl(200,70%,50%)]' },
  webchat: { Icon: Globe, bg: 'bg-[hsl(215,15%,45%)]' },
  email: { Icon: Mail, bg: 'bg-[hsl(220,70%,55%)]' },
  linkedin: { Icon: Linkedin, bg: 'bg-[hsl(201,100%,35%)]' },
};

interface VirtualizedRealtimeListProps {
  conversations: ConversationWithMessages[];
  selectedContactId: string | null;
  onSelectConversation: (contactId: string) => void;
  selectionMode?: boolean;
  selectedIds?: Set<string>;
  onToggleSelection?: (contactId: string) => void;
  onArchive?: (contactId: string) => void;
  onPin?: (contactId: string) => void;
  pinnedIds?: Set<string>;
  onResolve?: (contactId: string) => void;
  onTransfer?: (contactId: string) => void;
  onFavorite?: (contactId: string) => void;
  favoriteIds?: Set<string>;
  onSnooze?: (contactId: string, duration: string) => void;
}

const HEADER_HEIGHT = 32;
const EMPTY_SET = new Set<string>();

type FlatRow =
  | { kind: 'header'; key: string; label: string; count: number }
  | { kind: 'item'; key: string; conversation: ConversationWithMessages; isPinned: boolean };

function getConversationTime(c: ConversationWithMessages): number {
  if (c.lastMessage) return new Date(c.lastMessage.created_at).getTime();
  return new Date(c.contact.updated_at).getTime();
}

export function VirtualizedRealtimeList({
  conversations,
  selectedContactId,
  onSelectConversation,
  selectionMode = false,
  selectedIds = EMPTY_SET,
  onToggleSelection,
  onArchive,
  onPin,
  pinnedIds = EMPTY_SET,
  onResolve,
  onTransfer,
  onFavorite,
  favoriteIds = EMPTY_SET,
  onSnooze,
}: VirtualizedRealtimeListProps) {
  const parentRef = useRef<HTMLDivElement>(null);
  // R2-INB-056 (#349): o "sou eu?" da linha compara com public.profiles.id
  // (dono da FK contacts.assigned_to e chave do agentsMap) — o auth.users.id de
  // `user` é outro id e nunca casava, então a conversa atribuída a mim mesmo
  // exibia meu próprio mini-avatar como se fosse de outro atendente.
  const { profile } = useAuth();
  const currentProfileId = profile?.id ?? null;
  const agentsMap = useAgentsLite();
  const { density } = useDensity();
  const itemHeight = ITEM_HEIGHT_BY_DENSITY[density];

  const safeConversations = useMemo(() => {
    if (!Array.isArray(conversations)) return [];
    return conversations.filter(c => c?.contact?.id);
  }, [conversations]);

  // R2-INB-028: a ordem de exibição (não lidas primeiro, depois mais recentes)
  // é decidida em useInboxFilters e chega pronta em `conversations`. Aqui só
  // PARTICIONAMOS em grupos (Fixadas / Hoje / Ontem / Mais antigas) preservando
  // a ordem de entrada dentro de cada grupo. Reordenar por timestamp neste
  // ponto descartava a prioridade de não lidas: uma não lida antiga caía atrás
  // de uma lida mais recente do mesmo grupo de data.
  const flatRows = useMemo<FlatRow[]>(() => {
    const ordered = safeConversations;

    const pinned = ordered.filter(c => pinnedIds.has(c.contact.id));
    const rest = ordered.filter(c => !pinnedIds.has(c.contact.id));

    const today = rest.filter(c => isToday(new Date(getConversationTime(c))));
    const yesterday = rest.filter(c => isYesterday(new Date(getConversationTime(c))));
    const older = rest.filter(c => !isToday(new Date(getConversationTime(c))) && !isYesterday(new Date(getConversationTime(c))));

    const rows: FlatRow[] = [];
    if (pinned.length > 0) {
      rows.push({ kind: 'header', key: 'group-pinned', label: 'Fixadas', count: pinned.length });
      pinned.forEach(c => rows.push({ kind: 'item', key: c.contact.id, conversation: c, isPinned: true }));
    }
    if (today.length > 0) {
      rows.push({ kind: 'header', key: 'group-today', label: 'Hoje', count: today.length });
      today.forEach(c => rows.push({ kind: 'item', key: c.contact.id, conversation: c, isPinned: false }));
    }
    if (yesterday.length > 0) {
      rows.push({ kind: 'header', key: 'group-yesterday', label: 'Ontem', count: yesterday.length });
      yesterday.forEach(c => rows.push({ kind: 'item', key: c.contact.id, conversation: c, isPinned: false }));
    }
    if (older.length > 0) {
      rows.push({ kind: 'header', key: 'group-older', label: 'Mais antigas', count: older.length });
      older.forEach(c => rows.push({ kind: 'item', key: c.contact.id, conversation: c, isPinned: false }));
    }
    return rows;
  }, [safeConversations, pinnedIds]);

  const getScrollElement = useCallback(() => parentRef.current, []);
  const estimateSize = useCallback((index: number) => (flatRows[index]?.kind === 'header' ? HEADER_HEIGHT : itemHeight), [flatRows, itemHeight]);

  // TanStack Virtual retorna funcoes nao memoizaveis pelo React Compiler — mesma
  // limitacao ja aceita na baseline do ratchet para este mesmo hook.
  // eslint-disable-next-line react-hooks/incompatible-library
  const virtualizer = useVirtualizer({
    count: flatRows.length,
    getScrollElement,
    estimateSize,
    overscan: 8,
  });

  // @tanstack/react-virtual nao remede automaticamente linhas ja medidas
  // quando so o valor de retorno de estimateSize muda (density) — a mudanca
  // de referencia da funcao nao invalida o cache interno. Forca recalculo
  // explicito, senao as linhas ficam com a altura antiga (espacamento
  // errado / sobreposicao) ate um evento que mexa em `count`.
  useEffect(() => {
    virtualizer.measure();
  }, [density, virtualizer]);

  // O anel giratorio do card selecionado (.conversation-row-selected, PR #780)
  // roda em animation infinite via CSS puro — sem isso ele continua repintando
  // a GPU com a aba oculta/minimizada e ninguem olhando. Pausa via classe no
  // <html>, que animations.css usa pra travar animation-play-state.
  useEffect(() => {
    const root = document.documentElement;
    const sync = () => root.classList.toggle('tab-hidden', document.hidden);
    sync();
    document.addEventListener('visibilitychange', sync);
    return () => {
      document.removeEventListener('visibilitychange', sync);
      root.classList.remove('tab-hidden');
    };
  }, []);

  const handleClick = useCallback((contactId: string, e: React.SyntheticEvent) => {
    if (selectionMode && onToggleSelection) {
      e.preventDefault();
      onToggleSelection(contactId);
    } else {
      onSelectConversation(contactId);
    }
  }, [selectionMode, onToggleSelection, onSelectConversation]);

  if (flatRows.length === 0) {
    return null;
  }

  return (
    <div ref={parentRef} className="h-full overflow-auto scrollbar-thin">
      <div
        style={{
          height: `${virtualizer.getTotalSize()}px`,
          width: '100%',
          position: 'relative',
        }}
      >
        {virtualizer.getVirtualItems().map((virtualRow) => {
          const row = flatRows[virtualRow.index];
          if (row.kind === 'header') {
            return (
              <div
                key={row.key}
                style={{
                  position: 'absolute', top: 0, left: 0, width: '100%',
                  height: `${virtualRow.size}px`, transform: `translateY(${virtualRow.start}px)`,
                }}
              >
                <ConversationGroupHeader label={row.label} count={row.count} icon={row.key === 'group-pinned' ? Pin : undefined} />
              </div>
            );
          }
          const { conversation } = row;
          return (
            <ConversationRow
              key={row.key}
              conversation={conversation}
              virtualRow={virtualRow}
              selectedContactId={selectedContactId}
              isSelected={selectedIds.has(conversation.contact.id)}
              isPinned={row.isPinned}
              isFavorite={favoriteIds.has(conversation.contact.id)}
              selectionMode={selectionMode}
              onToggleSelection={onToggleSelection}
              handleClick={handleClick}
              onResolve={onResolve}
              onTransfer={onTransfer}
              onPin={onPin}
              onFavorite={onFavorite}
              onSnooze={onSnooze}
              onArchive={onArchive}
              currentProfileId={currentProfileId}
              agentsMap={agentsMap}
              density={density}
            />
          );
        })}
      </div>
    </div>
  );
}

// Rótulos do sentimento canônico (pt-BR). Não existe chave em inglês: o valor
// cru passa por normalizeSentiment, que traduz o legado EN e devolve
// `value: null` para desconhecido — aí o rótulo é 'sem análise', nunca um
// positivo/negativo inventado.
const SENTIMENT_LABEL: Record<Sentiment, string> = {
  positivo: 'positivo',
  neutro: 'neutro',
  negativo: 'negativo',
  critico: 'crítico',
};
const SEM_ANALISE = 'sem análise';

interface ConversationRowProps {
  conversation: ConversationWithMessages;
  virtualRow: VirtualItem;
  selectedContactId: string | null;
  isSelected: boolean;
  isPinned: boolean;
  isFavorite: boolean;
  selectionMode: boolean;
  onToggleSelection?: (contactId: string) => void;
  handleClick: (contactId: string, e: React.SyntheticEvent) => void;
  onResolve?: (contactId: string) => void;
  onTransfer?: (contactId: string) => void;
  onPin?: (contactId: string) => void;
  onFavorite?: (contactId: string) => void;
  onSnooze?: (contactId: string, duration: string) => void;
  onArchive?: (contactId: string) => void;
  /** profiles.id do usuário logado (não o auth id) — ver R2-INB-056. */
  currentProfileId: string | null;
  agentsMap: Map<string, AgentLite>;
  density: DensityMode;
}

// R2-SLA-003: a linha enviava o prazo FIXO de 5 min ao badge compacto,
// mesmo quando uma regra granular (por contato/empresa/cargo/tipo/fila/
// agente) determinava outro valor. O hook fica encapsulado neste filho
// estavel -- e nao dentro de ConversationRow -- para que cada linha tenha a
// propria assinatura de cache do react-query sem violar as regras de hooks
// nem a virtualizacao: o filho so monta quando ha SLA aberto e, quando
// monta, a chamada do hook e incondicional. A hierarquia do resolver NAO e
// duplicada aqui: passamos os atributos crus e useApplicableSLA decide.
const FALLBACK_FIRST_RESPONSE_MINUTES = 5;

interface ConversationSLABadgeProps {
  contact: ConversationWithMessages['contact'];
  firstMessageAt: Date;
}

const ConversationSLABadge = memo(({ contact, firstMessageAt }: ConversationSLABadgeProps) => {
  const { data } = useApplicableSLA({
    contactId: contact.id,
    company: contact.company,
    jobTitle: contact.job_title,
    contactType: contact.contact_type,
    queueId: contact.queue_id,
    agentId: contact.assigned_to,
  });

  return (
    <SLAIndicator
      firstMessageAt={firstMessageAt}
      firstResponseAt={null}
      firstResponseMinutes={data?.firstResponseMinutes ?? FALLBACK_FIRST_RESPONSE_MINUTES}
      compact
    />
  );
});

const ConversationRow = memo(({
  conversation,
  virtualRow,
  selectedContactId,
  isSelected,
  isPinned,
  isFavorite,
  selectionMode,
  onToggleSelection,
  handleClick,
  onResolve,
  onTransfer,
  onPin,
  onFavorite,
  onSnooze,
  onArchive,
  currentProfileId,
  agentsMap,
  density,
}: ConversationRowProps) => {
  const contactId = conversation.contact.id;
  const typeConfig = conversation.contact.contact_type ? CONTACT_TYPE_CONFIG[conversation.contact.contact_type] : null;
  const isVip = (conversation.contact.tags ?? []).some(t => t.toLowerCase() === 'vip');
  // Prioridade operacional canônica (EN) ou legado pt-BR ('alta'→'high');
  // ausente/desconhecido devolve `value: null` e nunca vira prioridade alta.
  const priority = normalizeOperationalPriority(conversation.contact.ai_priority);
  const sentiment = normalizeSentiment(conversation.contact.ai_sentiment);
  const isHighPriority = priority.value === 'high' || priority.value === 'urgent';
  const channelType = conversation.contact.channel_type;
  const channelBadge = channelType && channelType !== 'whatsapp' ? CHANNEL_BADGE_CONFIG[channelType] : null;
  const assignedToId = conversation.contact.assigned_to;
  const assignedAgent = assignedToId && assignedToId !== currentProfileId ? agentsMap.get(assignedToId) : null;
  // conversation_sla vem do embed do select (RealtimeService.fetchContacts:
  // '*, conversation_sla(...)'), presente em runtime mas ausente no tipo
  // genérico ContactRow (que so cobre as colunas da tabela contacts).
  // NAO e 1:1 com o contato — historico se acumula (ate 72 linhas por
  // contato em producao); so 1 linha por contato tem first_response_at
  // NULL (indice parcial ux_conversation_sla_open_per_contact = a "aberta"
  // agora). Pegar [0] sem filtro pega uma linha historica arbitraria e
  // pode mostrar "SLA violado" de um atendimento antigo ja resolvido.
  const slaRows = (conversation.contact as unknown as {
    conversation_sla?: Array<{ first_message_at: string | null; first_response_at: string | null }>;
  }).conversation_sla;
  const openSlaRow = slaRows?.find((r) => r.first_response_at === null);
  const firstMessageAt = openSlaRow?.first_message_at ?? (!slaRows?.length ? conversation.contact.created_at : undefined);
  const tags = conversation.contact.tags ?? [];

  const [snoozeOpen, setSnoozeOpen] = useState(false);

  // ConversationSLABadge chama useApplicableSLA (react-query) — sem um
  // QueryClient no contexto o useQuery lanca "No QueryClient set" e derruba
  // a linha inteira. A lista pode ser montada sem provider (arvores de
  // teste que rendem o componente direto), entao na ausencia do cliente
  // caimos no indicador com o prazo fixo anterior, sem chamar o hook e sem
  // instalar um QueryClient de reserva.
  const queryClient = useContext(QueryClientContext);

  const handleAction = (e: React.MouseEvent, handler: ((id: string) => void) | undefined, label: string) => {
    e.stopPropagation();
    if (handler) handler(contactId);
    else toast.info(`${label}: em breve`);
  };

  return (
    <div
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: `${virtualRow.size}px`,
        transform: `translateY(${virtualRow.start}px)`,
      }}
      // overflow-clip (não overflow-hidden): a altura da linha e uma
      // estimativa fixa (ITEM_HEIGHT_BY_DENSITY, sem measureElement no
      // virtualizer). Cargo preenchido + varias tags/badges quebrando em 2+
      // linhas (flex-wrap) pode superar essa estimativa (auditoria
      // 2026-09-26 mediu ate +68px no pior caso) — sem isso o excesso
      // vazava visualmente por cima da linha seguinte em vez de só cortar
      // dentro da própria linha. `overflow-hidden` cria um scroll container:
      // Tab até um botão da barra de ações (que só aparece no hover/foco)
      // rolava a linha por dentro e deslocava o conteúdo visível (achado na
      // 4a rodada da auditoria) — `overflow-clip` corta sem virar scroll
      // container.
      className="px-3 overflow-clip"
      data-testid="conversation-item"
    >
      <div
        className={cn(
          'w-full rounded-xl flex flex-col gap-1.5 transition-all text-left border group relative',
          ROW_CLASSES_BY_DENSITY[density],
          selectedContactId === contactId ? 'conversation-row-selected' : 'border-transparent hover:bg-muted/40',
          isSelected && selectedContactId !== contactId && 'bg-accent',
          isPinned && selectedContactId !== contactId && !isSelected && 'bg-muted/30'
        )}
      >
        <div className="flex items-center gap-3">
          {selectionMode && (
            <div className="flex-shrink-0 flex items-center">
              <Checkbox
                checked={isSelected}
                onCheckedChange={() => onToggleSelection?.(contactId)}
                aria-label={`Selecionar conversa com ${conversation.contact.name || 'contato sem nome'}`}
                className="data-[state=checked]:bg-primary"
              />
            </div>
          )}

          {/* role="button" e nao <button>: o conteudo tem <div> e <p>, que nao sao
              conteudo valido de button. Aqui nao ha mais aninhamento — checkbox e
              faixa de acoes sao irmaos deste elemento, entao o onKeyDown so
              dispara com o foco nele. */}
          <div
            role="button"
            tabIndex={0}
            onClick={(e) => handleClick(contactId, e)}
            onKeyDown={(e) => {
              if (e.key !== 'Enter' && e.key !== ' ') return;
              // Espaco segurado auto-repete; um <button> nativo ignora repeticao.
              if (e.repeat) return;
              e.preventDefault();
              handleClick(contactId, e);
            }}
            className="flex-1 min-w-0 flex items-center gap-3 text-left cursor-pointer outline-none rounded-md focus-visible:ring-2 focus-visible:ring-primary/40"
          >
          <div className="relative flex-shrink-0">
            <Avatar className="w-12 h-12">
              <AvatarImage src={conversation.contact.avatar_url || undefined} alt="" />
              <AvatarFallback className={cn(
                'text-xs font-semibold',
                getAvatarColor(conversation.contact.name || '?').bg,
                getAvatarColor(conversation.contact.name || '?').text
              )}>
                {getInitials(conversation.contact.name || '?')}
              </AvatarFallback>
            </Avatar>
            {channelBadge && (
              <span aria-hidden="true" className={cn('absolute -bottom-0.5 -left-0.5 w-5 h-5 rounded-full flex items-center justify-center ring-2 ring-card', channelBadge.bg)}>
                <channelBadge.Icon className="w-2.5 h-2.5 text-white" />
              </span>
            )}
            {assignedAgent && (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Avatar
                      className="absolute -bottom-0.5 -right-0.5 w-4 h-4 ring-2 ring-card"
                      role="img"
                      aria-label={`Atendido por ${assignedAgent.name}`}
                    >
                      <AvatarImage src={assignedAgent.avatar_url || undefined} alt="" />
                      <AvatarFallback className="text-3xs font-bold bg-secondary text-secondary-foreground">
                        {assignedAgent.name.slice(0, 2).toUpperCase()}
                      </AvatarFallback>
                    </Avatar>
                  </TooltipTrigger>
                  <TooltipContent side="top" className="text-xs font-medium">Atendido por {assignedAgent.name}</TooltipContent>
                </Tooltip>
              </TooltipProvider>
            )}
            {conversation.contact.ai_sentiment && (
              <span
                role="img"
                aria-label={`Sentimento: ${sentiment.value ? SENTIMENT_LABEL[sentiment.value] : SEM_ANALISE}`}
                className={cn(
                  'absolute -top-0.5 -right-0.5 w-3.5 h-3.5 rounded-full border-2 border-card',
                  sentiment.value === 'positivo' && 'bg-[hsl(var(--success))]',
                  sentiment.value === 'negativo' && 'bg-destructive',
                  sentiment.value === 'neutro' && 'bg-[hsl(var(--warning))]',
                  sentiment.value === 'critico' && 'bg-destructive',
                  // sem rótulo canônico (legado inventado/vazio) → cinza, não
                  // inventa positivo/negativo
                  sentiment.value === null && 'bg-muted'
                )}
                title={`Sentimento: ${sentiment.value ? SENTIMENT_LABEL[sentiment.value] : SEM_ANALISE}`}
              />
            )}
          </div>

          <div className="flex-1 min-w-0 overflow-hidden">
            <div className="flex items-center justify-between gap-2 mb-0.5">
              <div className="flex items-center gap-1.5 min-w-0 flex-1">
                <span className="font-semibold text-foreground truncate text-[15px]">
                  {(() => {
                    const firstName = (conversation.contact.name || 'Sem nome').split(' ')[0];
                    const displayName = conversation.contact.nickname?.trim() || firstName;
                    const company = conversation.contact.company;
                    return company ? `${displayName} · ${company}` : displayName;
                  })()}
                </span>
              </div>
              <div className="flex items-center gap-1.5 flex-shrink-0">
                {conversation.lastMessage && (
                  <span className="text-xs text-muted-foreground">
                    {formatDistanceToNow(new Date(conversation.lastMessage.created_at), {
                      addSuffix: false,
                      locale: ptBR,
                    })}
                  </span>
                )}
                <button
                  aria-label={isFavorite ? 'Remover favorito' : 'Favoritar conversa'}
                  onClick={(e) => handleAction(e, onFavorite, 'Favoritar')}
                  onKeyDown={(e) => e.stopPropagation()}
                  className="w-4 h-4 flex items-center justify-center text-muted-foreground/40 hover:text-warning transition-colors"
                >
                  <Star className={cn('w-3.5 h-3.5', isFavorite && 'fill-warning text-warning')} />
                </button>
              </div>
            </div>
            {conversation.contact.job_title && (
              <p className="text-2xs text-muted-foreground truncate -mt-0.5 mb-0.5">
                {conversation.contact.job_title}
              </p>
            )}
            <div className="flex items-center justify-between gap-2">
              <p className="text-[13px] text-muted-foreground truncate pr-2">
                {conversation.lastMessage?.content || 'Sem mensagens'}
              </p>
              {conversation.unreadCount > 0 && (
                <span className="flex-shrink-0 min-w-[22px] h-[22px] px-1.5 rounded-full flex items-center justify-center text-2xs font-bold bg-primary text-primary-foreground">
                  {conversation.unreadCount > 9 ? '9+' : conversation.unreadCount}
                </span>
              )}
            </div>
            {(typeConfig || isVip || isHighPriority || firstMessageAt || tags.length > 0) && (
              <div className="flex items-center gap-1 mt-1.5 flex-wrap">
                {typeConfig && (
                  <Badge variant="outline" className={cn('text-2xs px-1.5 py-0 h-4 border', typeConfig.badgeClass)}>
                    {typeConfig.label}
                  </Badge>
                )}
                {isVip && (
                  <Badge variant="outline" className="text-2xs px-1.5 py-0 h-4 bg-warning/15 text-warning border-warning/40">VIP</Badge>
                )}
                {isHighPriority && (
                  <Badge variant="outline" className="text-2xs px-1.5 py-0 h-4 bg-destructive/15 text-destructive border-destructive/40">Alta prioridade</Badge>
                )}
                {firstMessageAt && (queryClient ? (
                  <ConversationSLABadge
                    contact={conversation.contact}
                    firstMessageAt={new Date(firstMessageAt)}
                  />
                ) : (
                  <SLAIndicator
                    firstMessageAt={new Date(firstMessageAt)}
                    firstResponseAt={null}
                    firstResponseMinutes={FALLBACK_FIRST_RESPONSE_MINUTES}
                    compact
                  />
                ))}
                {tags.slice(0, 2).map((tag) => (
                  <Badge key={tag} variant="secondary" className="text-2xs px-1.5 py-0 h-4 bg-muted/50 border-border/20">{tag}</Badge>
                ))}
                {tags.length > 2 && (
                  <span className="text-2xs text-muted-foreground">+{tags.length - 2}</span>
                )}
              </div>
            )}
          </div>
          </div>
        </div>

        {/* Hover action buttons */}
        <div className="absolute bottom-2 left-0 right-0 flex items-center gap-0.5 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 pointer-events-none group-hover:pointer-events-auto group-focus-within:pointer-events-auto transition-all duration-150 pl-[60px]">
          <TooltipProvider delayDuration={200}>
            <Tooltip>
              <TooltipTrigger asChild>
                <button
                  aria-label="Resolver conversa"
                  onClick={(e) => handleAction(e, onResolve, 'Resolver')}
                  className="w-7 h-7 rounded-lg flex items-center justify-center text-muted-foreground hover:text-emerald-500 hover:bg-emerald-500/10 active:scale-90 transition-all duration-150"
                >
                  <CheckCircle2 className="w-3.5 h-3.5" />
                </button>
              </TooltipTrigger>
              <TooltipContent side="bottom" className="text-xs font-medium">Resolver</TooltipContent>
            </Tooltip>
            <Tooltip>
              <TooltipTrigger asChild>
                <button
                  aria-label="Transferir conversa"
                  onClick={(e) => handleAction(e, onTransfer, 'Transferir')}
                  className="w-7 h-7 rounded-lg flex items-center justify-center text-muted-foreground hover:text-primary hover:bg-primary/10 active:scale-90 transition-all duration-150"
                >
                  <UserCheck className="w-3.5 h-3.5" />
                </button>
              </TooltipTrigger>
              <TooltipContent side="bottom" className="text-xs font-medium">Transferir</TooltipContent>
            </Tooltip>
            <Tooltip>
              <TooltipTrigger asChild>
                <button
                  aria-label="Fixar conversa"
                  onClick={(e) => handleAction(e, onPin, 'Fixar')}
                  className="w-7 h-7 rounded-lg flex items-center justify-center text-muted-foreground hover:text-amber-500 hover:bg-amber-500/10 active:scale-90 transition-all duration-150"
                >
                  <Pin className="w-3.5 h-3.5" />
                </button>
              </TooltipTrigger>
              <TooltipContent side="bottom" className="text-xs font-medium">Fixar</TooltipContent>
            </Tooltip>
            <Popover open={snoozeOpen} onOpenChange={setSnoozeOpen}>
              <Tooltip>
                <TooltipTrigger asChild>
                  <PopoverTrigger asChild>
                    <button
                      aria-label="Adiar conversa"
                      onClick={(e) => { e.stopPropagation(); if (!onSnooze) { toast.info('Adiar: em breve'); setSnoozeOpen(false); } }}
                      className="w-7 h-7 rounded-lg flex items-center justify-center text-muted-foreground hover:text-sky-500 hover:bg-sky-500/10 active:scale-90 transition-all duration-150"
                    >
                      <AlarmClock className="w-3.5 h-3.5" />
                    </button>
                  </PopoverTrigger>
                </TooltipTrigger>
                <TooltipContent side="bottom" className="text-xs font-medium">Adiar</TooltipContent>
              </Tooltip>
              {onSnooze && (
                <PopoverContent align="start" className="w-44 p-1" onClick={(e) => e.stopPropagation()}>
                  {SNOOZE_OPTIONS.map((opt) => (
                    <button
                      key={opt.value}
                      onClick={() => { onSnooze(contactId, opt.value); setSnoozeOpen(false); }}
                      className="w-full text-left px-2 py-1.5 rounded-md text-sm hover:bg-muted transition-colors"
                    >
                      {opt.label}
                    </button>
                  ))}
                </PopoverContent>
              )}
            </Popover>
            <Tooltip>
              <TooltipTrigger asChild>
                <button
                  aria-label="Arquivar conversa"
                  onClick={(e) => handleAction(e, onArchive, 'Arquivar')}
                  className="w-7 h-7 rounded-lg flex items-center justify-center text-muted-foreground hover:text-destructive hover:bg-destructive/10 active:scale-90 transition-all duration-150"
                >
                  <Archive className="w-3.5 h-3.5" />
                </button>
              </TooltipTrigger>
              <TooltipContent side="bottom" className="text-xs font-medium">Arquivar</TooltipContent>
            </Tooltip>
          </TooltipProvider>
        </div>
      </div>
    </div>
  );
});
